{
    "name": "septianfr/support-septian",
    "description": "Support Septian F. R. — Aplikasi Web Manajemen Email Customer Support PHP 8.1+ dengan Google Gmail API OAuth 2.0 & PHPMailer SMTP Gmail App Password",
    "type": "project",
    "license": "proprietary",
    "require": {
        "php": ">=8.1",
        "ext-pdo": "*",
        "ext-pdo_mysql": "*",
        "ext-openssl": "*",
        "ext-mbstring": "*",
        "ext-json": "*",
        "ext-dom": "*",
        "ext-fileinfo": "*",
        "google/apiclient": "^2.18",
        "phpmailer/phpmailer": "^6.9"
    },
    "suggest": {
        "ext-imap": "Diperlukan apabila menggunakan mode koneksi Google App Password untuk membaca Inbox/Sent/Drafts via IMAP."
    },
    "scripts": {
        "pre-autoload-dump": "Google\\Task\\Composer::cleanup"
    },
    "extra": {
        "google/apiclient-services": [
            "Gmail",
            "Oauth2"
        ]
    },
    "config": {
        "optimize-autoloader": true,
        "sort-packages": true,
        "vendor-dir": "mail/support/vendor"
    }
}

/* ============================================================================
   SUPPORT SEPTIAN — Mailbox, Thread View, Rich Editor & Template Styles
   Path: /mail/support/assets/css/email.css
   ============================================================================ */

/* Mailbox Card & Toolbar */
.mailbox-card {
    padding: 0;
    overflow: hidden;
}

.mailbox-toolbar {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    padding: 10px 16px;
    border-bottom: 1px solid var(--border-color);
    background: var(--bg-canvas);
    flex-wrap: wrap;
}

.toolbar-left,
.toolbar-right,
.toolbar-actions,
.pagination-controls {
    display: flex;
    align-items: center;
    gap: 6px;
    flex-wrap: wrap;
}

.mailbox-meta {
    font-size: 12.5px;
    color: var(--text-muted);
    margin-right: 6px;
}

/* Mailbox Rows */
.mailbox-list {
    display: flex;
    flex-direction: column;
}

.mail-row {
    display: grid;
    grid-template-columns: 32px 32px 210px 1fr 90px;
    align-items: center;
    gap: 10px;
    padding: 11px 16px;
    border-bottom: 1px solid var(--border-color);
    background: var(--bg-surface);
    color: var(--text-primary);
    transition: background-color 0.1s ease;
    cursor: pointer;
}

.mail-row:last-child {
    border-bottom: none;
}

.mail-row:hover {
    background: #f8fafc;
}

.mail-row.is-unread {
    background: #f4f8ff;
}

.mail-row.is-unread .mail-sender,
.mail-row.is-unread .mail-subject {
    font-weight: 700;
    color: var(--text-primary);
}

.mail-star-btn {
    border: none;
    background: transparent;
    cursor: pointer;
    font-size: 18px;
    line-height: 1;
    color: #cbd5e1;
    padding: 4px;
}
.mail-star-btn.is-starred {
    color: #eab308;
}
.mail-star-btn:hover {
    color: #ca8a04;
}

.mail-sender {
    font-size: 13.5px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.mail-content-col {
    min-width: 0;
    display: flex;
    align-items: baseline;
    gap: 6px;
    white-space: nowrap;
    overflow: hidden;
}

.mail-subject {
    font-size: 13.5px;
    color: var(--text-primary);
    flex-shrink: 0;
    max-width: 55%;
    overflow: hidden;
    text-overflow: ellipsis;
}

.mail-snippet {
    font-size: 13px;
    color: var(--text-muted);
    overflow: hidden;
    text-overflow: ellipsis;
}

.mail-date {
    text-align: right;
    font-size: 12.5px;
    color: var(--text-muted);
    white-space: nowrap;
}

/* Compact Dashboard Mail List */
.mail-list-compact .mail-row-compact {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    padding: 11px 0;
    border-bottom: 1px solid var(--border-color);
    text-decoration: none;
    color: inherit;
}
.mail-list-compact .mail-row-compact:last-child {
    border-bottom: none;
}
.mail-list-compact .mail-row-compact:hover {
    text-decoration: none;
}
.mail-row-compact-main {
    min-width: 0;
    flex: 1;
}
.mail-row-compact-top {
    display: flex;
    align-items: baseline;
    gap: 8px;
}
.mail-row-compact-sender {
    font-size: 13.5px;
    font-weight: 600;
    color: var(--text-primary);
}
.mail-row-compact-subject {
    font-size: 13.5px;
    color: var(--text-secondary);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}
.mail-row-compact.is-unread .mail-row-compact-subject {
    font-weight: 700;
    color: var(--text-primary);
}
.mail-row-compact-snippet {
    font-size: 12.5px;
    color: var(--text-muted);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

/* Thread Detail View */
.thread-container {
    display: flex;
    flex-direction: column;
    gap: 16px;
    margin-bottom: 20px;
}

.thread-message {
    padding: 20px 24px;
}

.thread-msg-header {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 14px;
    padding-bottom: 14px;
    border-bottom: 1px solid var(--border-color);
    margin-bottom: 16px;
}

.sender-block {
    display: flex;
    align-items: center;
    gap: 12px;
}

.sender-avatar {
    width: 40px;
    height: 40px;
    border-radius: 50%;
    background: var(--accent-soft);
    color: var(--accent);
    font-weight: 700;
    font-size: 15px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
}

.sender-name-line {
    font-size: 14.5px;
    color: var(--text-primary);
}
.sender-email {
    font-size: 13px;
    color: var(--text-muted);
    margin-left: 4px;
}
.recipient-meta {
    font-size: 12.5px;
    color: var(--text-muted);
    margin-top: 2px;
}

.msg-date {
    font-size: 12.5px;
    color: var(--text-muted);
    white-space: nowrap;
}

.email-rendered-content {
    font-size: 14.5px;
    line-height: 1.7;
    color: var(--text-primary);
    overflow-wrap: anywhere;
}
.email-rendered-content img {
    max-width: 100%;
    height: auto;
}
.email-rendered-content table {
    max-width: 100%;
}

.attachments-strip {
    margin-top: 18px;
    padding-top: 14px;
    border-top: 1px solid var(--border-color);
}
.attachments-title {
    font-size: 12.5px;
    font-weight: 600;
    color: var(--text-muted);
    margin-bottom: 10px;
}
.attachments-list {
    display: flex;
    flex-wrap: wrap;
    gap: 10px;
}
.attachment-card {
    display: inline-flex;
    align-items: center;
    gap: 10px;
    padding: 8px 14px;
    border: 1px solid var(--border-color);
    border-radius: var(--radius-sm);
    background: var(--bg-canvas);
    color: var(--text-primary);
    font-size: 13px;
    text-decoration: none;
}
.attachment-card:hover {
    border-color: var(--accent);
    background: var(--accent-soft);
    text-decoration: none;
}
.att-size {
    font-size: 12px;
    color: var(--text-muted);
}

/* Reply / Compose Rich Editor */
.reply-mode-tabs {
    display: flex;
    gap: 6px;
    border-bottom: 1px solid var(--border-color);
    padding-bottom: 12px;
    margin-bottom: 16px;
    flex-wrap: wrap;
}

.mode-tab {
    height: 34px;
    padding: 0 14px;
    border: 1px solid var(--border-color);
    border-radius: var(--radius-sm);
    background: var(--bg-surface);
    color: var(--text-secondary);
    font-family: inherit;
    font-size: 13px;
    font-weight: 600;
    cursor: pointer;
}
.mode-tab.is-active {
    background: var(--accent);
    color: #ffffff;
    border-color: var(--accent);
}

.editor-meta-grid {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 14px;
}

.var-insert-bar {
    display: flex;
    align-items: center;
    flex-wrap: wrap;
    gap: 6px;
    margin-bottom: 12px;
    padding: 8px 12px;
    background: var(--bg-canvas);
    border: 1px solid var(--border-color);
    border-radius: var(--radius-sm);
}

.var-label {
    font-size: 12px;
    font-weight: 600;
    color: var(--text-muted);
    margin-right: 4px;
}

.var-btn {
    border: 1px solid var(--border-strong);
    background: var(--bg-surface);
    color: var(--accent);
    font-family: var(--font-mono);
    font-size: 11.5px;
    padding: 3px 8px;
    border-radius: 4px;
    cursor: pointer;
}
.var-btn:hover {
    background: var(--accent-soft);
    border-color: var(--accent);
}

.editor-toolbar {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 10px;
    flex-wrap: wrap;
    padding: 8px 12px;
    background: var(--bg-canvas);
    border: 1px solid var(--border-strong);
    border-bottom: none;
    border-radius: var(--radius-sm) var(--radius-sm) 0 0;
}

.toolbar-btn-group {
    display: flex;
    align-items: center;
    gap: 6px;
    flex-wrap: wrap;
}

.tool-btn {
    height: 30px;
    padding: 0 10px;
    border: 1px solid var(--border-color);
    background: var(--bg-surface);
    color: var(--text-primary);
    border-radius: 4px;
    font-family: inherit;
    font-size: 12.5px;
    cursor: pointer;
}
.tool-btn:hover {
    background: var(--bg-subtle);
}

.rich-editor {
    min-height: 220px;
    max-height: 520px;
    overflow-y: auto;
    padding: 16px;
    border: 1px solid var(--border-strong);
    border-radius: 0 0 var(--radius-sm) var(--radius-sm);
    background: var(--bg-surface);
    font-size: 14.5px;
    line-height: 1.65;
    color: var(--text-primary);
}
.rich-editor-lg {
    min-height: 290px;
}
.rich-editor:focus {
    outline: none;
    border-color: var(--accent);
}

.file-list-preview {
    margin-top: 8px;
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
    font-size: 12.5px;
    color: var(--text-secondary);
}

.editor-footer-actions {
    margin-top: 18px;
    padding-top: 16px;
    border-top: 1px solid var(--border-color);
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    flex-wrap: wrap;
}
.editor-footer-left {
    display: flex;
    align-items: center;
    gap: 10px;
    flex-wrap: wrap;
}
.editor-identity-note {
    font-size: 12.5px;
    color: var(--text-muted);
}

/* Templates Management & Preview */
.filter-bar {
    display: flex;
    align-items: center;
    gap: 6px;
    margin-bottom: 16px;
    flex-wrap: wrap;
}

.filter-tab {
    padding: 7px 14px;
    border-radius: var(--radius-sm);
    border: 1px solid var(--border-color);
    background: var(--bg-surface);
    color: var(--text-secondary);
    font-size: 13px;
    font-weight: 600;
    text-decoration: none;
}
.filter-tab:hover { background: var(--bg-subtle); text-decoration: none; }
.filter-tab.is-active {
    background: var(--accent);
    color: #ffffff;
    border-color: var(--accent);
}

.templates-workspace {
    display: grid;
    grid-template-columns: 1.1fr 1fr;
    gap: 20px;
    align-items: start;
}

.template-list {
    display: flex;
    flex-direction: column;
}

.template-row {
    padding: 14px 0;
    border-bottom: 1px solid var(--border-color);
    display: flex;
    flex-direction: column;
    gap: 10px;
}
.template-row:last-child { border-bottom: none; }

.template-row-title {
    display: flex;
    align-items: center;
    gap: 8px;
    font-size: 14.5px;
}
.default-marker {
    font-size: 11.5px;
    font-weight: 700;
    color: var(--accent);
}
.template-row-meta {
    font-size: 12.5px;
    color: var(--text-muted);
    margin-top: 2px;
}
.template-row-desc {
    font-size: 13px;
    color: var(--text-secondary);
    margin-top: 4px;
}
.template-row-actions {
    display: flex;
    flex-wrap: wrap;
    gap: 6px;
}

/* Standalone Preview Workspace */
.segmented-control {
    display: inline-flex;
    background: var(--bg-subtle);
    padding: 3px;
    border-radius: var(--radius-sm);
    border: 1px solid var(--border-color);
}
.seg-btn {
    border: none;
    background: transparent;
    padding: 6px 12px;
    border-radius: 4px;
    font-family: inherit;
    font-size: 12.5px;
    font-weight: 600;
    color: var(--text-secondary);
    cursor: pointer;
}
.seg-btn.is-active {
    background: var(--bg-surface);
    color: var(--text-primary);
    box-shadow: 0 1px 2px rgba(0, 0, 0, 0.06);
}

.preview-workspace {
    display: grid;
    grid-template-columns: 360px 1fr;
    gap: 20px;
    align-items: start;
}

.preview-mail-meta {
    padding-bottom: 12px;
    margin-bottom: 14px;
    border-bottom: 1px solid var(--border-color);
    font-size: 13px;
    color: var(--text-secondary);
    display: flex;
    flex-direction: column;
    gap: 4px;
}

.preview-stage {
    background: #eef2f6;
    border-radius: var(--radius-md);
    padding: 20px;
    display: flex;
    justify-content: center;
    overflow-x: auto;
}

.standalone-preview-frame {
    width: 100%;
    max-width: 660px;
    height: 760px;
    border: 1px solid var(--border-color);
    border-radius: var(--radius-md);
    background: #ffffff;
    transition: max-width 0.2s ease;
}
.preview-stage.is-mobile .standalone-preview-frame {
    max-width: 375px;
}

.preview-iframe {
    width: 100%;
    height: 600px;
    border: none;
    background: #f5f7fa;
    display: block;
}

/* ============================================================================
   SUPPORT SEPTIAN — Responsive Stylesheet (Tablet, Android & iPhone)
   Path: /mail/support/assets/css/responsive.css
   ============================================================================ */

@media (max-width: 1180px) {
    .stats-grid {
        grid-template-columns: repeat(3, minmax(0, 1fr));
    }
    .dashboard-columns,
    .templates-workspace,
    .preview-workspace,
    .two-col-grid {
        grid-template-columns: 1fr;
    }
}

@media (max-width: 900px) {
    .mobile-menu-btn {
        display: inline-flex;
    }

    .app-sidebar {
        position: fixed;
        top: var(--header-height);
        left: 0;
        bottom: 0;
        z-index: 60;
        transform: translateX(-100%);
        transition: transform 0.2s cubic-bezier(0.16, 1, 0.3, 1);
        box-shadow: 0 12px 32px rgba(15, 23, 42, 0.16);
    }

    .app-sidebar.is-open {
        transform: translateX(0);
    }

    .sidebar-backdrop.is-open {
        display: block;
        position: fixed;
        inset: var(--header-height) 0 0 0;
        z-index: 50;
        background: rgba(15, 23, 42, 0.35);
    }

    .app-main {
        padding: 18px 16px 36px 16px;
    }

    .admin-chip-name {
        display: none;
    }

    .mail-row {
        grid-template-columns: 28px 28px 1fr auto;
        grid-template-rows: auto auto;
        gap: 4px 8px;
        padding: 12px 14px;
    }
    .mail-row .mail-sender {
        grid-column: 3 / 4;
        grid-row: 1;
    }
    .mail-row .mail-date {
        grid-column: 4 / 5;
        grid-row: 1;
    }
    .mail-row .mail-content-col {
        grid-column: 3 / 5;
        grid-row: 2;
        flex-direction: column;
        gap: 2px;
    }
    .mail-row .mail-subject {
        max-width: 100%;
    }
}

@media (max-width: 640px) {
    .app-header {
        padding: 0 12px;
        gap: 8px;
    }

    .brand-name {
        font-size: 15px;
    }

    .conn-indicator {
        display: none;
    }

    .header-search input[type="search"] {
        font-size: 13.5px;
        padding-left: 34px;
    }
    .header-search .search-icon {
        left: 10px;
    }

    .page-header {
        flex-direction: column;
        align-items: stretch;
    }

    .stats-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    .form-grid-2,
    .form-grid-3,
    .editor-meta-grid,
    .check-grid {
        grid-template-columns: 1fr;
    }

    .connection-banner {
        flex-direction: column;
        align-items: flex-start;
    }

    .btn, .tool-btn, .mode-tab, .nav-item {
        min-height: 40px;
    }

    .thread-msg-header {
        flex-direction: column;
    }

    .preview-stage {
        padding: 10px;
    }

    .standalone-preview-frame {
        height: 600px;
    }
}

/* ============================================================================
   SUPPORT SEPTIAN — Core Application Stylesheet (Google Gmail + Support Modern)
   Path: /mail/support/assets/css/style.css
   ============================================================================ */

:root {
    --bg-canvas: #f8fafc;
    --bg-surface: #ffffff;
    --bg-subtle: #f1f5f9;
    --bg-hover: #f1f5f9;
    --border-color: #e2e8f0;
    --border-strong: #cbd5e1;

    --text-primary: #0f172a;
    --text-secondary: #475569;
    --text-muted: #64748b;

    --accent: #1a73e8;
    --accent-hover: #1557b0;
    --accent-soft: #e8f0fe;

    --success: #15803d;
    --success-bg: #f0fdf4;
    --warning: #b45309;
    --warning-bg: #fffbeb;
    --danger: #b91c1c;
    --danger-bg: #fef2f2;

    --radius-sm: 6px;
    --radius-md: 10px;
    --radius-lg: 14px;
    --header-height: 60px;
    --sidebar-width: 256px;

    --font-sans: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, 'Segoe UI', Helvetica, Arial, sans-serif;
    --font-mono: 'IBM Plex Mono', ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
}

*, *::before, *::after {
    box-sizing: border-box;
}

html, body {
    margin: 0;
    padding: 0;
    font-family: var(--font-sans);
    font-size: 14.5px;
    line-height: 1.55;
    color: var(--text-primary);
    background-color: var(--bg-canvas);
    -webkit-font-smoothing: antialiased;
}

a {
    color: var(--accent);
    text-decoration: none;
}
a:hover {
    text-decoration: underline;
}

code {
    font-family: var(--font-mono);
    font-size: 0.88em;
    background: var(--bg-subtle);
    padding: 2px 6px;
    border-radius: 4px;
    color: var(--text-primary);
}

.tabular-nums {
    font-variant-numeric: tabular-nums;
}
.nowrap {
    white-space: nowrap;
}
.muted {
    color: var(--text-muted);
}
.text-success { color: var(--success); }
.text-warning { color: var(--warning); }
.text-danger  { color: var(--danger); }

/* ----------------------------------------------------------------------------
   Shell & Top Header
   ---------------------------------------------------------------------------- */
.app-shell {
    min-height: 100vh;
    display: flex;
    flex-direction: column;
}

.app-header {
    position: sticky;
    top: 0;
    z-index: 40;
    height: var(--header-height);
    background: var(--bg-surface);
    border-bottom: 1px solid var(--border-color);
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 16px;
    padding: 0 20px;
}

.header-left {
    display: flex;
    align-items: center;
    gap: 12px;
    flex-shrink: 0;
}

.brand-lockup {
    display: flex;
    align-items: center;
    gap: 10px;
    color: var(--text-primary);
    text-decoration: none;
}
.brand-lockup:hover {
    text-decoration: none;
}

.brand-logo {
    border-radius: 8px;
    object-fit: cover;
    display: block;
    background: var(--accent-soft);
}

.brand-name {
    font-size: 17px;
    font-weight: 700;
    letter-spacing: -0.02em;
    white-space: nowrap;
}

.header-search {
    flex: 1;
    max-width: 560px;
    position: relative;
    display: flex;
    align-items: center;
}

.header-search .search-icon {
    position: absolute;
    left: 14px;
    color: var(--text-muted);
    pointer-events: none;
}

.header-search input[type="search"] {
    width: 100%;
    height: 40px;
    padding: 0 36px 0 42px;
    border: 1px solid var(--border-color);
    border-radius: var(--radius-md);
    background: var(--bg-subtle);
    color: var(--text-primary);
    font-family: inherit;
    font-size: 14px;
    transition: background-color 0.15s ease, border-color 0.15s ease;
}

.header-search input[type="search"]:focus {
    outline: none;
    background: var(--bg-surface);
    border-color: var(--accent);
}

.search-clear {
    position: absolute;
    right: 10px;
    color: var(--text-muted);
    font-size: 18px;
    padding: 2px 6px;
    text-decoration: none;
}

.header-right {
    display: flex;
    align-items: center;
    gap: 14px;
    flex-shrink: 0;
}

.conn-indicator {
    font-size: 12.5px;
    font-weight: 600;
    white-space: nowrap;
    padding: 6px 10px;
    border-radius: var(--radius-sm);
    border: 1px solid var(--border-color);
    color: var(--text-secondary);
    text-decoration: none;
}
.conn-indicator:hover { text-decoration: none; background: var(--bg-subtle); }
