(function () {
    'use strict';

    const csrfMeta = document.querySelector('meta[name="csrf-token"]');
    const baseMeta = document.querySelector('meta[name="base-path"]');

    const BASE_PATH = baseMeta ? baseMeta.getAttribute('content').replace(/\/$/, '') : '/mail/support';
    const CSRF_TOKEN = csrfMeta ? csrfMeta.getAttribute('content') : '';

    function buildUrl(relativePath) {
        const clean = String(relativePath || '').replace(/^\/+/, '');
        return BASE_PATH + '/' + clean;
    }

    function escapeHtml(str) {
        const div = document.createElement('div');
        div.textContent = String(str ?? '');
        return div.innerHTML;
    }

    function showToast(message, type = 'info', duration = 4200) {
        const container = document.getElementById('toastContainer');
        if (!container) return;

        const el = document.createElement('div');
        el.className = 'toast toast-' + type;
        el.textContent = message;
        container.appendChild(el);

        setTimeout(() => {
            el.style.opacity = '0';
            el.style.transition = 'opacity 0.2s ease';
            setTimeout(() => el.remove(), 220);
        }, duration);
    }

    function confirmModal({ title = 'Konfirmasi', body = 'Apakah Anda yakin?', okText = 'Ya, Lanjutkan', danger = false }) {
        return new Promise((resolve) => {
            const modal  = document.getElementById('confirmModal');
            const titleEl= document.getElementById('confirmModalTitle');
            const bodyEl = document.getElementById('confirmModalBody');
            const okBtn  = document.getElementById('confirmModalOk');
            const cancelBtn = document.getElementById('confirmModalCancel');
            const closeBtn  = document.getElementById('confirmModalClose');

            if (!modal) {
                resolve(true);
                return;
            }

            titleEl.textContent = title;
            bodyEl.innerHTML = body;
            okBtn.textContent = okText;
            okBtn.className = danger ? 'btn btn-danger-outline' : 'btn btn-primary';
            modal.hidden = false;

            const cleanup = (result) => {
                modal.hidden = true;
                okBtn.removeEventListener('click', onOk);
                cancelBtn.removeEventListener('click', onCancel);
                closeBtn.removeEventListener('click', onCancel);
                resolve(result);
            };

            const onOk = () => cleanup(true);
            const onCancel = () => cleanup(false);

            okBtn.addEventListener('click', onOk);
            cancelBtn.addEventListener('click', onCancel);
            closeBtn.addEventListener('click', onCancel);
        });
    }

    async function apiGet(relativePath) {
        const res = await fetch(buildUrl(relativePath), {
            method: 'GET',
            credentials: 'same-origin',
            headers: {
                'Accept': 'application/json',
                'X-Requested-With': 'XMLHttpRequest'
            }
        });
        const data = await res.json().catch(() => ({ ok: false, message: 'Respons server tidak valid.' }));
        if (!res.ok && data.ok !== true) {
            throw new Error(data.message || 'Permintaan gagal (' + res.status + ')');
        }
        return data;
    }

    async function apiPost(relativePath, payload) {
        const res = await fetch(buildUrl(relativePath), {
            method: 'POST',
            credentials: 'same-origin',
            headers: {
                'Content-Type': 'application/json',
                'Accept': 'application/json',
                'X-CSRF-Token': CSRF_TOKEN,
                'X-Requested-With': 'XMLHttpRequest'
            },
            body: JSON.stringify(payload || {})
        });
        const data = await res.json().catch(() => ({ ok: false, message: 'Respons server tidak valid.' }));
        if (!res.ok && data.ok !== true) {
            throw new Error(data.message || 'Permintaan gagal (' + res.status + ')');
        }
        return data;
    }

    async function apiPostForm(relativePath, formData) {
        if (!formData.has('csrf_token')) {
            formData.append('csrf_token', CSRF_TOKEN);
        }
        const res = await fetch(buildUrl(relativePath), {
            method: 'POST',
            credentials: 'same-origin',
            headers: {
                'Accept': 'application/json',
                'X-CSRF-Token': CSRF_TOKEN,
                'X-Requested-With': 'XMLHttpRequest'
            },
            body: formData
        });
        const data = await res.json().catch(() => ({ ok: false, message: 'Respons server tidak valid.' }));
        if (!res.ok && data.ok !== true) {
            throw new Error(data.message || 'Permintaan gagal (' + res.status + ')');
        }
        return data;
    }

    // Mobile Sidebar Drawer
    document.addEventListener('DOMContentLoaded', () => {
        const menuBtn  = document.getElementById('mobileMenuBtn');
        const sidebar  = document.getElementById('appSidebar');
        const backdrop = document.getElementById('sidebarBackdrop');

        const closeDrawer = () => {
            if (sidebar) sidebar.classList.remove('is-open');
            if (backdrop) backdrop.classList.remove('is-open');
        };

        if (menuBtn && sidebar && backdrop) {
            menuBtn.addEventListener('click', () => {
                sidebar.classList.toggle('is-open');
                backdrop.classList.toggle('is-open');
            });
            backdrop.addEventListener('click', closeDrawer);
        }
    });

    window.SupportApp = {
        BASE_PATH,
        CSRF_TOKEN,
        buildUrl,
        escapeHtml,
        showToast,
        confirmModal,
        apiGet,
        apiPost,
        apiPostForm
    };
})();

/**
 * Support Septian — Compose, Reply, Reply All & Forward Editor Controller
 * Path: /mail/support/assets/js/editor.js
 */

(function () {
    'use strict';

    const App = window.SupportApp;
    if (!App) return;

    document.addEventListener('DOMContentLoaded', () => {
        initThreadActions();
        initEmailEditor();
    });

    function initThreadActions() {
        const bar = document.getElementById('threadActionBar');
        if (!bar) return;

        const messageId = bar.dataset.messageId;
        bar.querySelectorAll('[data-single-action]').forEach((btn) => {
            btn.addEventListener('click', async () => {
                const action = btn.dataset.singleAction;
                if (action === 'trash') {
                    const ok = await App.confirmModal({
                        title: 'Pindahkan ke Sampah',
                        body: 'Pindahkan pesan ini ke folder Sampah Gmail?',
                        okText: 'Pindahkan ke Sampah',
                        danger: true
                    });
                    if (!ok) return;
                }

                try {
                    const res = await App.apiPost('api/actions.php', { action, ids: [messageId] });
                    App.showToast(res.message || 'Aksi berhasil.', 'success');
                    if (['trash', 'archive', 'spam'].includes(action)) {
                        setTimeout(() => { window.location.href = App.buildUrl('inbox.php'); }, 650);
                    } else if (action === 'star' || action === 'unstar') {
                        btn.dataset.singleAction = action === 'star' ? 'unstar' : 'star';
                        btn.textContent = action === 'star' ? 'Hapus Bintang' : 'Beri Bintang';
                    }
                } catch (err) {
                    App.showToast(err.message, 'error');
                }
            });
        });
    }

    function initEmailEditor() {
        const form = document.getElementById('emailEditorForm');
        const richEditor = document.getElementById('richEditor');
        const hiddenBody = document.getElementById('bodyHtmlHidden');
        const tplSelect  = document.getElementById('templateSelector');
        const toInput    = document.getElementById('editorTo');
        const ccInput    = document.getElementById('editorCc');
        const subjInput  = document.getElementById('editorSubject');
        const recNameEl  = document.getElementById('recipientNameInput');
        const attInput   = document.getElementById('editorAttachments');
        const attPreview = document.getElementById('attachmentPreviewList');
        const btnSend    = document.getElementById('btnSendEmail');
        const btnDraft   = document.getElementById('btnSaveDraft');
        const btnPreview = document.getElementById('btnPreviewEmail');

        if (!form || !richEditor) return;

        function applyTemplateOption(option, updateSubject = false) {
            if (!option || !option.value) return;
            const rawBody = option.dataset.body || '';
            const rawSubj = option.dataset.subject || '';
            const recName = (recNameEl && recNameEl.value.trim()) || form.dataset.replyName || 'Pelanggan';
            const origSubj = form.dataset.origSubject || (subjInput ? subjInput.value : '');

            const hydrated = rawBody
                .replaceAll('{nama_penerima}', App.escapeHtml(recName))
                .replaceAll('{subjek}', App.escapeHtml(origSubj))
                .replaceAll('{nama_pengirim}', App.escapeHtml(form.dataset.adminName || 'Support Septian F. R.'))
                .replaceAll('{nama_perusahaan}', 'Support Septian F. R.')
                .replaceAll('{website}', 'https://septianfr.web.id')
                .replaceAll('{email_support}', 'support.septianfr@gmail.com')
                .replaceAll('{isi_pesan}', 'Tulis pesan Anda di sini...');

            richEditor.innerHTML = hydrated;

            if (updateSubject && subjInput && rawSubj) {
                if (form.dataset.mode === 'compose' && subjInput.value.trim() !== '') {
                    return;
                }
                const resolvedSubj = rawSubj.replaceAll('{subjek}', origSubj.replace(/^(re|fwd):\s*/i, ''));
                if (resolvedSubj.trim() !== '') {
                    subjInput.value = resolvedSubj;
                }
            }
        }

        function loadDefaultTemplateForMode(mode) {
            if (!tplSelect) return;
            const options = Array.from(tplSelect.options);
            const match = options.find((o) => o.dataset.category === mode && o.dataset.default === '1')
                || options.find((o) => o.dataset.category === mode);

            if (match) {
                tplSelect.value = match.value;
                applyTemplateOption(match, false);
            }
        }

        // Muat template default otomatis saat halaman dibuka
        loadDefaultTemplateForMode(form.dataset.mode || 'compose');

        if (tplSelect) {
            tplSelect.addEventListener('change', () => {
                const selected = tplSelect.options[tplSelect.selectedIndex];
                applyTemplateOption(selected, form.dataset.mode !== 'compose');
            });
        }

        // Reply / Reply All / Forward mode tabs pada view-email.php
        document.querySelectorAll('[data-reply-mode]').forEach((tab) => {
            tab.addEventListener('click', () => {
                const mode = tab.dataset.replyMode;
                document.querySelectorAll('[data-reply-mode]').forEach((t) => t.classList.remove('is-active'));
                tab.classList.add('is-active');

                form.dataset.mode = mode;
                const origSubj = (form.dataset.origSubject || '').replace(/^(re|fwd):\s*/i, '');

                if (mode === 'reply') {
                    form.dataset.endpoint = App.buildUrl('api/reply.php');
                    if (toInput) toInput.value = form.dataset.replyTo || '';
                    if (ccInput) ccInput.value = '';
                    if (subjInput) subjInput.value = 'Re: ' + origSubj;
                    if (btnSend) btnSend.textContent = 'Kirim Balasan';
                } else if (mode === 'reply_all') {
                    form.dataset.endpoint = App.buildUrl('api/reply-all.php');
                    if (toInput) toInput.value = form.dataset.replyAllTo || form.dataset.replyTo || '';
                    if (ccInput) ccInput.value = form.dataset.replyAllCc || '';
                    if (subjInput) subjInput.value = 'Re: ' + origSubj;
                    if (btnSend) btnSend.textContent = 'Kirim Balas Semua';
                } else if (mode === 'forward') {
                    form.dataset.endpoint = App.buildUrl('api/forward.php');
                    if (toInput) { toInput.value = ''; toInput.focus(); }
                    if (ccInput) ccInput.value = '';
                    if (subjInput) subjInput.value = 'Fwd: ' + origSubj;
                    if (btnSend) btnSend.textContent = 'Teruskan Email';
                }

                loadDefaultTemplateForMode(mode);
            });
        });

        // Rich Text Formatting Buttons
        document.querySelectorAll('.tool-btn[data-cmd]').forEach((btn) => {
            btn.addEventListener('click', () => {
                richEditor.focus();
                document.execCommand(btn.dataset.cmd, false, null);
            });
        });

        const btnLink = document.getElementById('btnInsertLink');
        if (btnLink) {
            btnLink.addEventListener('click', () => {
                const url = prompt('Masukkan URL tautan (harus diawali https:// atau http://):', 'https://septianfr.web.id');
                if (url && /^https?:\/\//i.test(url.trim())) {
                    richEditor.focus();
                    document.execCommand('createLink', false, url.trim());
                } else if (url) {
                    App.showToast('URL harus diawali https:// atau http://', 'warning');
                }
            });
        }

        // Dynamic Variable Quick Insert
        document.querySelectorAll('[data-insert-var]').forEach((btn) => {
            btn.addEventListener('click', () => {
                const token = btn.dataset.insertVar;
                richEditor.focus();
                document.execCommand('insertText', false, token);
            });
        });

        // Attachment File Preview
        if (attInput && attPreview) {
            attInput.addEventListener('change', () => {
                const files = Array.from(attInput.files || []);
                if (!files.length) {
                    attPreview.innerHTML = '';
                    return;
                }
                attPreview.innerHTML = files.map((f) => {
                    const kb = (f.size / 1024).toFixed(1);
                    return `<span>${App.escapeHtml(f.name)} (${kb} KB)</span>`;
                }).join(' &middot; ');
            });
        }

        // Live Preview Email HTML
        const previewModal = document.getElementById('emailPreviewModal');
        const previewFrame = document.getElementById('emailPreviewFrame');
        const closePreview = () => { if (previewModal) previewModal.hidden = true; };

        const closeBtn1 = document.getElementById('closePreviewModal');
        const closeBtn2 = document.getElementById('closePreviewModalBtn');
        if (closeBtn1) closeBtn1.addEventListener('click', closePreview);
        if (closeBtn2) closeBtn2.addEventListener('click', closePreview);

        if (btnPreview && previewModal && previewFrame) {
            btnPreview.addEventListener('click', async () => {
                try {
                    const res = await App.apiPost('api/templates.php', {
                        action: 'preview',
                        subject: subjInput ? subjInput.value : 'Preview Email',
                        body_html: richEditor.innerHTML,
                        nama_penerima: (recNameEl && recNameEl.value.trim()) || 'Pelanggan',
                        email_penerima: toInput ? toInput.value.trim() : ''
                    });
                    previewFrame.srcdoc = res.html;
                    previewModal.hidden = false;
                } catch (err) {
                    App.showToast(err.message, 'error');
                }
            });
        }

        // Save Draft to Gmail
        if (btnDraft) {
            btnDraft.addEventListener('click', async () => {
                hiddenBody.value = richEditor.innerHTML;
                const fd = new FormData(form);
                btnDraft.disabled = true;
                try {
                    const res = await App.apiPostForm('api/drafts.php', fd);
                    const draftInput = document.getElementById('draftIdInput');
                    if (draftInput && res.draft && res.draft.draft_id) {
                        draftInput.value = res.draft.draft_id;
                    }
                    App.showToast(res.message || 'Draft disimpan ke Gmail.', 'success');
                } catch (err) {
                    App.showToast(err.message, 'error');
                } finally {
                    btnDraft.disabled = false;
                }
            });
        }

        // Submit Send Email (WAJIB Konfirmasi Admin)
        form.addEventListener('submit', async (ev) => {
            ev.preventDefault();
            hiddenBody.value = richEditor.innerHTML;

            const toVal = toInput ? toInput.value.trim() : '';
            const subjVal = subjInput ? subjInput.value.trim() : '';

            if (!toVal || !subjVal) {
                App.showToast('Penerima (Kepada) dan Subjek email wajib diisi.', 'warning');
                return;
            }

            const confirmed = await App.confirmModal({
                title: 'Konfirmasi Pengiriman Email',
                body: `
                    <p style="margin:0 0 8px 0;">Pastikan informasi email berikut sudah benar sebelum dikirim melalui akun resmi <strong>support.septianfr@gmail.com</strong>:</p>
                    <div style="background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px;padding:10px 12px;font-size:13px;">
                        <div><strong>Kepada:</strong> ${App.escapeHtml(toVal)}</div>
                        ${ccInput && ccInput.value.trim() ? '<div><strong>Cc:</strong> ' + App.escapeHtml(ccInput.value.trim()) + '</div>' : ''}
                        <div><strong>Subjek:</strong> ${App.escapeHtml(subjVal)}</div>
                    </div>
                `,
                okText: 'Ya, Kirim Sekarang'
            });

            if (!confirmed) return;

            const fd = new FormData(form);
            fd.set('confirmed', '1');

            const endpoint = form.dataset.endpoint || App.buildUrl('api/send.php');
            const relativeEndpoint = endpoint.replace(App.BASE_PATH + '/', '');

            if (btnSend) {
                btnSend.disabled = true;
                btnSend.dataset.origText = btnSend.textContent;
                btnSend.textContent = 'Mengirim...';
            }

            try {
                const res = await App.apiPostForm(relativeEndpoint, fd);
                App.showToast(res.message || 'Email berhasil dikirim!', 'success', 5000);
                setTimeout(() => {
                    window.location.href = App.buildUrl('sent.php');
                }, 900);
            } catch (err) {
                App.showToast(err.message, 'error', 6000);
            } finally {
                if (btnSend) {
                    btnSend.disabled = false;
                    btnSend.textContent = btnSend.dataset.origText || 'Kirim Email';
                }
            }
        });
    }
})();

/**
 * Support Septian — Dashboard Stats & Mailbox Folder Controller (Vanilla JS)
 * Path: /mail/support/assets/js/inbox.js
 */

(function () {
    'use strict';

    const App = window.SupportApp;
    if (!App) return;

    // ------------------------------------------------------------------------
    // 1. Dashboard Controller
    // ------------------------------------------------------------------------
    async function loadDashboardData() {
        const statsGrid = document.getElementById('dashboardStatsGrid');
        const recentBox = document.getElementById('dashboardRecentEmails');
        if (!statsGrid || statsGrid.dataset.connected !== '1') return;

        try {
            const [statsRes, inboxRes] = await Promise.all([
                App.apiGet('api/messages.php?stats=1'),
                App.apiGet('api/messages.php?folder=inbox&limit=8')
            ]);

            if (statsRes.ok && statsRes.stats) {
                const s = statsRes.stats;
                setText('statInboxTotal', s.inbox_total);
                setText('statInboxUnread', s.inbox_unread);
                setText('statSentTotal', s.sent_total);
                setText('statDraftsTotal', s.drafts_total);
                setText('statStarredTotal', s.starred_total);

                const sidebarBadge = document.getElementById('sidebarInboxUnread');
                if (sidebarBadge && s.inbox_unread > 0) {
                    sidebarBadge.textContent = String(s.inbox_unread);
                }
            }

            if (recentBox) {
                const list = inboxRes.messages || [];
                if (list.length === 0) {
                    recentBox.innerHTML = '<div class="empty-state"><p class="muted">Kotak masuk kosong.</p></div>';
                } else {
                    recentBox.innerHTML = list.map((m) => `
                        <a href="${App.buildUrl('view-email.php?id=' + encodeURIComponent(m.id) + '&folder=inbox')}"
                           class="mail-row-compact ${m.is_unread ? 'is-unread' : ''}">
                            <div class="mail-row-compact-main">
                                <div class="mail-row-compact-top">
                                    <span class="mail-row-compact-sender">${App.escapeHtml(m.from_name)}</span>
                                    <span class="mail-row-compact-subject">${App.escapeHtml(m.subject)}</span>
                                </div>
                                <div class="mail-row-compact-snippet">${App.escapeHtml(m.snippet || m.from_email)}</div>
                            </div>
                            <span class="mail-date tabular-nums">${App.escapeHtml(m.date_short)}</span>
                        </a>
                    `).join('');
                }
            }
        } catch (err) {
            if (recentBox) {
                recentBox.innerHTML = `<div class="alert alert-danger"><span>${App.escapeHtml(err.message)}</span></div>`;
            }
            App.showToast(err.message, 'error');
        }
    }

    function setText(id, value) {
        const el = document.getElementById(id);
        if (el) el.textContent = String(value ?? '0');
    }

    // ------------------------------------------------------------------------
    // 2. Mailbox Folder Controller (Inbox, Sent, Drafts, Starred, Spam, Trash)
    // ------------------------------------------------------------------------
    function initMailbox() {
        const container = document.getElementById('mailboxContainer');
        if (!container) return;

        const folder    = container.dataset.folder || 'inbox';
        const query     = container.dataset.query || '';
        const connected = container.dataset.connected === '1';

        const listEl      = document.getElementById('mailboxList');
        const metaEl      = document.getElementById('mailboxMetaInfo');
        const selectAllEl = document.getElementById('selectAllMails');
        const btnPrev     = document.getElementById('btnPrevPage');
        const btnNext     = document.getElementById('btnNextPage');
        const btnRefresh  = document.getElementById('btnRefreshFolder');

        let tokenHistory = [''];
        let currentIndex = 0;
        let nextPageToken = null;

        if (!connected) {
            if (metaEl) metaEl.textContent = 'Belum terhubung';
            return;
        }

        async function fetchPage(pageToken) {
            if (listEl) {
                listEl.innerHTML = '<div class="loading-rows">' + '<div class="skeleton-row"></div>'.repeat(6) + '</div>';
            }
            if (selectAllEl) selectAllEl.checked = false;

            const endpoint = query !== ''
                ? `api/search.php?q=${encodeURIComponent(query)}&folder=${encodeURIComponent(folder)}${pageToken ? '&pageToken=' + encodeURIComponent(pageToken) : ''}`
                : `api/messages.php?folder=${encodeURIComponent(folder)}${pageToken ? '&pageToken=' + encodeURIComponent(pageToken) : ''}`;

            try {
                const res = await App.apiGet(endpoint);
                const msgs = res.messages || [];
                nextPageToken = res.next_page_token || null;

                if (metaEl) {
                    metaEl.textContent = `Halaman ${currentIndex + 1} · ${msgs.length} pesan ditampilkan`;
                }
                if (btnPrev) btnPrev.disabled = currentIndex === 0;
                if (btnNext) btnNext.disabled = !nextPageToken;

                renderMessages(msgs);
            } catch (err) {
                if (listEl) {
                    listEl.innerHTML = `<div class="empty-state"><p class="text-danger"><strong>Gagal memuat email</strong></p><p class="muted">${App.escapeHtml(err.message)}</p></div>`;
                }
                App.showToast(err.message, 'error');
            }
        }

        function renderMessages(messages) {
            if (!listEl) return;
            if (!messages.length) {
                listEl.innerHTML = '<div class="empty-state"><p><strong>Tidak ada email di folder ini.</strong></p><p class="muted">Semua pesan dari Gmail yang cocok akan muncul di sini.</p></div>';
                return;
            }

            listEl.innerHTML = messages.map((m) => {
                const targetUrl = folder === 'drafts' && m.draft_id
                    ? App.buildUrl(`compose.php?draft_id=${encodeURIComponent(m.draft_id)}&to=${encodeURIComponent(m.to)}&subject=${encodeURIComponent(m.subject)}`)
                    : App.buildUrl(`view-email.php?id=${encodeURIComponent(m.id)}&folder=${encodeURIComponent(folder)}`);

                const senderDisplay = folder === 'sent'
                    ? 'Kepada: ' + (m.to || m.from_name)
                    : m.from_name;

                return `
                    <div class="mail-row ${m.is_unread ? 'is-unread' : ''}" data-id="${App.escapeHtml(m.id)}" data-href="${targetUrl}">
                        <input type="checkbox" class="mail-select-cb" value="${App.escapeHtml(m.id)}" aria-label="Pilih email">
                        <button type="button" class="mail-star-btn ${m.is_starred ? 'is-starred' : ''}" data-star-id="${App.escapeHtml(m.id)}" data-starred="${m.is_starred ? '1' : '0'}" title="Bintang">${m.is_starred ? '★' : '☆'}</button>
                        <div class="mail-sender">${App.escapeHtml(senderDisplay)}</div>
                        <div class="mail-content-col">
                            <span class="mail-subject">${App.escapeHtml(m.subject)}</span>
                            <span class="mail-snippet">${m.snippet ? '— ' + App.escapeHtml(m.snippet) : ''}</span>
                        </div>
                        <div class="mail-date tabular-nums">${App.escapeHtml(m.date_short)}</div>
                    </div>
                `;
            }).join('');

            // Row click opens email detail
            listEl.querySelectorAll('.mail-row').forEach((row) => {
                row.addEventListener('click', (ev) => {
                    if (ev.target.closest('input[type="checkbox"]') || ev.target.closest('.mail-star-btn')) {
                        return;
                    }
                    window.location.href = row.dataset.href;
                });
            });

            // Inline star toggle
            listEl.querySelectorAll('.mail-star-btn').forEach((btn) => {
                btn.addEventListener('click', async (ev) => {
                    ev.stopPropagation();
                    const id = btn.dataset.starId;
                    const currentlyStarred = btn.dataset.starred === '1';
                    const action = currentlyStarred ? 'unstar' : 'star';
                    btn.disabled = true;
                    try {
                        await App.apiPost('api/actions.php', { action, ids: [id] });
                        btn.dataset.starred = currentlyStarred ? '0' : '1';
                        btn.classList.toggle('is-starred', !currentlyStarred);
                        btn.textContent = currentlyStarred ? '☆' : '★';
                    } catch (err) {
                        App.showToast(err.message, 'error');
                    } finally {
                        btn.disabled = false;
                    }
                });
            });
        }

        function getSelectedIds() {
            return Array.from(document.querySelectorAll('.mail-select-cb:checked')).map((cb) => cb.value);
        }

        if (selectAllEl) {
            selectAllEl.addEventListener('change', () => {
                document.querySelectorAll('.mail-select-cb').forEach((cb) => {
                    cb.checked = selectAllEl.checked;
                });
            });
        }

        // Bulk actions toolbar
        document.querySelectorAll('[data-bulk-action]').forEach((btn) => {
            btn.addEventListener('click', async () => {
                const action = btn.dataset.bulkAction;
                const ids = getSelectedIds();
                if (!ids.length) {
                    App.showToast('Pilih minimal satu email terlebih dahulu.', 'warning');
                    return;
                }

                if (action === 'delete') {
                    const ok = await App.confirmModal({
                        title: 'Hapus Permanen Email',
                        body: `Anda akan menghapus permanen <strong>${ids.length} email</strong>. Tindakan ini tidak dapat dibatalkan.`,
                        okText: 'Hapus Permanen',
                        danger: true
                    });
                    if (!ok) return;
                }

                try {
                    const res = await App.apiPost('api/actions.php', { action, ids });
                    App.showToast(res.message || 'Aksi berhasil.', 'success');
                    fetchPage(tokenHistory[currentIndex]);
                } catch (err) {
                    App.showToast(err.message, 'error');
                }
            });
        });

        if (btnNext) {
            btnNext.addEventListener('click', () => {
                if (!nextPageToken) return;
                currentIndex++;
                tokenHistory[currentIndex] = nextPageToken;
                fetchPage(nextPageToken);
            });
        }

        if (btnPrev) {
            btnPrev.addEventListener('click', () => {
                if (currentIndex <= 0) return;
                currentIndex--;
                fetchPage(tokenHistory[currentIndex]);
            });
        }

        if (btnRefresh) {
            btnRefresh.addEventListener('click', () => {
                tokenHistory = [''];
                currentIndex = 0;
                fetchPage('');
                App.showToast('Memperbarui daftar email dari Gmail...', 'info', 2000);
            });
        }

        fetchPage('');
    }

    document.addEventListener('DOMContentLoaded', () => {
        loadDashboardData();
        initMailbox();

        const btnDashRefresh = document.getElementById('btnRefreshDashboard');
        if (btnDashRefresh) {
            btnDashRefresh.addEventListener('click', () => {
                loadDashboardData();
                App.showToast('Menyegarkan data Gmail...', 'info', 2000);
            });
        }
    });
})();

/**
 * Support Septian — Template Management & Live Preview Controller
 * Path: /mail/support/assets/js/templates.js
 */

(function () {
    'use strict';

    const App = window.SupportApp;
    if (!App) return;

    document.addEventListener('DOMContentLoaded', () => {
        initTemplateManager();
        initStandalonePreview();
    });

    function initTemplateManager() {
        const form = document.getElementById('templateForm');
        if (!form) return;

        const headingEl = document.getElementById('templateFormHeading');
        const idEl      = document.getElementById('tplId');
        const actionEl  = document.getElementById('tplAction');
        const nameEl    = document.getElementById('tplName');
        const catEl     = document.getElementById('tplCategory');
        const subjEl    = document.getElementById('tplSubject');
        const descEl    = document.getElementById('tplDescription');
        const bodyEl    = document.getElementById('tplBodyHtml');
        const defEl     = document.getElementById('tplIsDefault');
        const btnNew    = document.getElementById('btnNewTemplate');
        const btnReset  = document.getElementById('btnResetTemplateForm');
        const btnPrev   = document.getElementById('btnLivePreviewTemplate');

        function resetForm() {
            idEl.value = '';
            actionEl.value = 'create';
            headingEl.textContent = 'Buat Template Baru';
            nameEl.value = '';
            catEl.value = 'reply';
            subjEl.value = 'Re: {subjek}';
            descEl.value = '';
            bodyEl.value = '<p>Halo <strong>{nama_penerima}</strong>,</p>\n<p>Terima kasih telah menghubungi <strong>{nama_perusahaan}</strong>.</p>\n<p>{isi_pesan}</p>\n<p>Apabila masih ada hal lain yang dapat kami bantu, silakan balas email ini.</p>';
            defEl.checked = false;
        }

        if (btnNew) {
            btnNew.addEventListener('click', () => {
                resetForm();
                nameEl.focus();
                document.getElementById('templateEditorCard')?.scrollIntoView({ behavior: 'smooth' });
            });
        }
        if (btnReset) btnReset.addEventListener('click', resetForm);

        // Sisipkan token variabel ke posisi kursor textarea
        document.querySelectorAll('[data-insert-tpl-var]').forEach((btn) => {
            btn.addEventListener('click', () => {
                const token = btn.dataset.insertTplVar;
                const start = bodyEl.selectionStart || bodyEl.value.length;
                const end   = bodyEl.selectionEnd || bodyEl.value.length;
                bodyEl.value = bodyEl.value.substring(0, start) + token + bodyEl.value.substring(end);
                bodyEl.focus();
                bodyEl.setSelectionRange(start + token.length, start + token.length);
            });
        });

        // Edit template
        document.querySelectorAll('[data-edit-template]').forEach((btn) => {
            btn.addEventListener('click', async () => {
                const id = btn.dataset.editTemplate;
                try {
                    const res = await App.apiGet('api/templates.php?id=' + encodeURIComponent(id));
                    const t = res.template;
                    idEl.value = t.id;
                    actionEl.value = 'update';
                    headingEl.textContent = 'Edit Template: ' + t.name;
                    nameEl.value = t.name;
                    catEl.value = t.category;
                    subjEl.value = t.subject_template || '';
                    descEl.value = t.description || '';
                    bodyEl.value = t.body_html || '';
                    defEl.checked = Number(t.is_default) === 1;
                    document.getElementById('templateEditorCard')?.scrollIntoView({ behavior: 'smooth' });
                } catch (err) {
                    App.showToast(err.message, 'error');
                }
            });
        });

        // Duplicate template
        document.querySelectorAll('[data-duplicate-template]').forEach((btn) => {
            btn.addEventListener('click', async () => {
                try {
                    const res = await App.apiPost('api/templates.php', {
                        action: 'duplicate',
                        id: btn.dataset.duplicateTemplate
                    });
                    App.showToast(res.message, 'success');
                    setTimeout(() => window.location.reload(), 550);
                } catch (err) {
                    App.showToast(err.message, 'error');
                }
            });
        });

        // Set Default template
        document.querySelectorAll('[data-default-template]').forEach((btn) => {
            btn.addEventListener('click', async () => {
                try {
                    const res = await App.apiPost('api/templates.php', {
                        action: 'set_default',
                        id: btn.dataset.defaultTemplate
                    });
                    App.showToast(res.message, 'success');
                    setTimeout(() => window.location.reload(), 550);
                } catch (err) {
                    App.showToast(err.message, 'error');
                }
            });
        });

        // Delete template
        document.querySelectorAll('[data-delete-template]').forEach((btn) => {
            btn.addEventListener('click', async () => {
                const name = btn.dataset.tplName || 'template ini';
                const ok = await App.confirmModal({
                    title: 'Hapus Template Email',
                    body: `Apakah Anda yakin ingin menghapus template <strong>${App.escapeHtml(name)}</strong>?`,
                    okText: 'Hapus Template',
                    danger: true
                });
                if (!ok) return;

                try {
                    const res = await App.apiPost('api/templates.php', {
                        action: 'delete',
                        id: btn.dataset.deleteTemplate
                    });
                    App.showToast(res.message, 'success');
                    setTimeout(() => window.location.reload(), 550);
                } catch (err) {
                    App.showToast(err.message, 'error');
                }
            });
        });

        // Live preview modal
        const modal = document.getElementById('tplPreviewModal');
        const frame = document.getElementById('tplPreviewFrame');
        const closeModal = () => { if (modal) modal.hidden = true; };
        document.getElementById('closeTplPreviewModal')?.addEventListener('click', closeModal);
        document.getElementById('closeTplPreviewBtn')?.addEventListener('click', closeModal);

        if (btnPrev && modal && frame) {
            btnPrev.addEventListener('click', async () => {
                try {
                    const res = await App.apiPost('api/templates.php', {
                        action: 'preview',
                        subject: subjEl.value || 'Preview Support Septian',
                        body_html: bodyEl.value
                    });
                    frame.srcdoc = res.html;
                    modal.hidden = false;
                } catch (err) {
                    App.showToast(err.message, 'error');
                }
            });
        }

        // Submit Create / Update
        form.addEventListener('submit', async (ev) => {
            ev.preventDefault();
            try {
                const res = await App.apiPost('api/templates.php', {
                    action: actionEl.value,
                    id: idEl.value,
                    name: nameEl.value.trim(),
                    category: catEl.value,
                    subject_template: subjEl.value.trim(),
                    description: descEl.value.trim(),
                    body_html: bodyEl.value,
                    is_default: defEl.checked ? 1 : 0
                });
                App.showToast(res.message || 'Template disimpan.', 'success');
                setTimeout(() => window.location.reload(), 600);
            } catch (err) {
                App.showToast(err.message, 'error');
            }
        });
    }

    function initStandalonePreview() {
        const select = document.getElementById('previewTemplateSelect');
        const frame  = document.getElementById('standalonePreviewFrame');
        const stage  = document.getElementById('previewStage');
        const subjOut= document.getElementById('previewRenderedSubject');
        const btnRef = document.getElementById('btnRefreshPreviewPage');

        if (!select || !frame) return;

        async function updatePreview() {
            const opt = select.options[select.selectedIndex];
            if (!opt) return;

            try {
                const res = await App.apiPost('api/templates.php', {
                    action: 'preview',
                    subject: opt.dataset.subject || document.getElementById('simSubjek').value,
                    body_html: opt.dataset.body || '',
                    nama_penerima: document.getElementById('simNamaPenerima').value,
                    email_penerima: document.getElementById('simEmailPenerima').value,
                    isi_pesan: document.getElementById('simIsiPesan').value
                });
                if (subjOut) subjOut.textContent = res.subject;
                frame.srcdoc = res.html;
            } catch (err) {
                App.showToast(err.message, 'error');
            }
        }

        select.addEventListener('change', updatePreview);
        if (btnRef) btnRef.addEventListener('click', updatePreview);

        document.querySelectorAll('#viewportToggle [data-viewport]').forEach((btn) => {
            btn.addEventListener('click', () => {
                document.querySelectorAll('#viewportToggle [data-viewport]').forEach((b) => b.classList.remove('is-active'));
                btn.classList.add('is-active');
                if (stage) {
                    stage.classList.toggle('is-mobile', btn.dataset.viewport === 'mobile');
                }
            });
        });
    }
})();
